function qmOpen(nav){qmClose();const m=document.createElement('div');m.className='igqm';m.innerHTML=[['monitor','Diseño Web','#5b8cff'],['android','App Android','#3ddc97'],['ui','UI/UX','#9a7bff']].map((c,i)=>`<button style="--h:${c[2]};--d:${i*45}ms" onclick="qmGo('${c[1]}')">${I(c[0],14)}<span>${c[1]}</span></button>`).join('')+`<button class="qa" style="--d:135ms" onclick="qmClose();to('new')">${I('lib',13)}<span>Ver plantillas</span></button>`;
 const sh=document.createElement('div');sh.className='igsh';sh.onclick=qmClose;nav.closest('.ph').append(sh,m);nav.closest('.ph').classList.add('qopen');requestAnimationFrame(()=>{m.classList.add('igon');sh.classList.add('igon')})}
